# -*- coding: utf-8 -*-
"""Дополнительная привязка статей к вопросам по тексту (поле qx в manifest.json).
Статья уже отнесена к теме по названию (поле qn); здесь в её тексте ищутся формулировки узких вопросов той же темы.
Повторный запуск безопасен: поле qx пересчитывается заново. Запуск: /tmp/venv/bin/python textq.py"""
import os, re, sys, json
sys.dont_write_bytecode = True
ROOT = '/home/user/Ekzameny-v-institute-MVD'; os.chdir(ROOT)
import fitz
K = '.github/downloader/krim/'
R = lambda a, b: set(range(a, b + 1))
# вопрос: (тема — вопросы, к одному из которых статья уже отнесена по названию; выражение; минимум совпадений)
RULES = {
 2: (R(1, 5), r'систем\w+ криминалистической тактики|структур\w+ криминалистической тактики', 2),
 5: (R(1, 5) | R(13, 44), r'тактическ\w+ (операци|комбинаци)\w+|оперативно-тактическ\w+ комбинаци\w+', 4),
 8: (R(6, 11), r'(подготовительн|рабоч|заключительн|общ|детальн)\w+ (этап|стади)\w+', 4),
 9: (R(6, 12), r'запахов\w+ след\w+|микрообъект\w+|микрочастиц\w+|микросле\w+', 4),
 10: (R(6, 12), r'протокол\w* осмотра места происшествия', 4),
 14: (R(13, 14), r'тактическ\w+ при[её]м\w+|тактик\w+ задержания|подготов\w+ к задержанию|протокол\w* задержания', 4),
 24: (R(23, 27), r'подготов\w+ к (предъявлению|опознанию|производству опознания|проведению опознания)|подготовительн\w+ (этап|стади)\w+|предварительн\w+ допрос\w+ опознающ\w+|подбор\w* статист\w+', 2),
 25: (R(23, 27), r'опознани\w+ (людей|человека|лица|живых лиц)|предъявлени\w+ лица для опознания|по фотографи\w+|вне визуального наблюдения', 4),
 26: (R(23, 27), r'опознани\w+ (предмет|труп|вещ|оруж)\w*|предъявлени\w+ (предмет|труп)\w* для опознания|предъявлени\w+ для опознания (предмет|труп)\w*', 3),
 27: (R(23, 27), r'протокол\w* предъявления для опознания|протокол\w* опознания|видеозапис\w+|фотосъемк\w+', 4),
 29: (R(28, 33), r'подготов\w+ к (обыску|производству обыска|проведению обыска)|подготовительн\w+ (этап|стади)\w+|поисков\w+ (прибор|техник|средств)\w+|металлоискател\w+|тайник\w+', 4),
 31: (R(28, 33), r'личн\w+ обыск\w*', 4),
 32: (R(28, 33), r'обыск\w* (в |)(помещени|жилищ|квартир|офис)\w+', 4),
 33: (R(28, 33), r'протокол\w* (обыска|выемки)|фиксаци\w+ (хода|результат)\w*', 3),
 35: (R(34, 36), r'подготов\w+ к (следственному эксперименту|производству|проведению)|подготовительн\w+ (этап|стади)\w+', 2),
 36: (R(34, 36), r'тактическ\w+ (при[её]м|услови|правил|рекомендаци)\w+|сходств\w+ услови\w+|неоднократн\w+|многократн\w+', 3),
 38: (R(37, 40), r'подготов\w+ к (проверке показаний|производству проверки|проведению проверки|производству|проведению)|подготовительн\w+ (этап|стади)\w+', 2),
 39: (R(37, 40), r'тактическ\w+ (при[её]м|услови|правил|рекомендаци)\w+', 3),
 40: (R(37, 40), r'протокол\w* проверки показаний|видеозапис\w+|фотосъемк\w+|видеосъемк\w+', 4),
 42: (R(41, 44), r'цел\w+ (контроля и записи|данного следственного действия|производства контроля)|(основани|услови)\w+ (для |)(производства|проведения) контроля и записи', 2),
 43: (R(41, 44), r'ходатайств\w+|постановлени\w+ о (производстве|возбуждении)|судебн\w+ решени\w+', 4),
 44: (R(41, 44), r'фонограмм\w+|осмотр\w* и прослушивани\w+|протокол\w* осмотра', 3),
}
man = json.load(open(K + 'manifest.json', encoding='utf-8')); add = 0; n = 0
for m in man:
    if m['type'] != 'article': continue
    m['qx'] = []
    if m.get('garbled') or not os.path.exists(m['dst']): continue
    d = fitz.open(m['dst']); t = ' '.join(' '.join(p.get_text() for p in d).lower().replace('ё', 'е').replace('-\n', '').split()); n += 1
    for q, (theme, rx, k) in RULES.items():
        if q in m['qn'] or not (theme & set(m['qn'])): continue
        if len(re.findall(rx.replace('[её]', 'е'), t)) >= k: m['qx'].append(q)
    add += len(m['qx'])
json.dump(man, open(K + 'manifest.json', 'w', encoding='utf-8'), ensure_ascii=False, indent=0)
import collections
c = collections.Counter(q for m in man if m['type'] == 'article' for q in m['qx'])
print('статей просмотрено', n, 'добавлено привязок', add, sorted(c.items()))
